        return [clip(sign(sx, tx)), clip(sign(sy, ty))]

    def step_away(tx, ty):
        return [clip(-sign(sx, tx)), clip(-sign(sy, ty))]

    def best_by_manhattan(points, prefer_far=False):
        if not points:
            return None
