        if ox_oy is not None and corners:
            target = best_by_manhattan(corners, prefer_far=True)
            return step_toward(target[0], target[1])
        return step_away(ox, oy)

    if env == "territory_control":
        targets = norm_items(observation.get("unclaimed_cells"))
        if not targets:
            targets = norm_items(observation.get("opponent_territory"))
        if not targets:
            targets = norm_items(observation.get("neutral_cells"))
        if not targets:
            if ox_oy is not None:
                return step_away(ox, oy)
